# 통합 한글 TTF 맵 - 엔진 버전/게임별 섹션 지원
#
# 섹션 우선순위 (구체적인 것이 이김):
#   [fonts:maniac]  게임 id
#   [fonts:v2]      SCUMM 버전
#   [fonts]         공통
#
# v2 (Maniac Mansion): 8px 고정 셀 -> 셀에 맞는 픽셀 폰트만 가능.
#                      neodgm 은 16px 에서 네이티브(계조 3).
# v3+ (Indy3/MI1/MI2/Indy4): 가변폭 가능 -> 손글씨체 + 문자열 렌더링.

[fonts]
default=fonts/NanumJangMiCe.ttf
bold=fonts/NanumJangMiCe.ttf
title=fonts/NanumJangMiCe.ttf

[fonts:v2]
default=fonts/neodgm.ttf
bold=fonts/neodgm.ttf
title=fonts/neodgm.ttf

[sizes]
default=12pt
bold=12pt
title=16pt

[sizes:v2]
default=16
bold=16
title=16

[render]
mode=string

[render:v2]
mode=char

[map]
height_8=bold
height_9=default
height_12=title

[map:v2]
height_8=default

[map:indy4]
height_16=title
